apiVersion: core.openfeature.dev/v1alpha2
kind: FeatureFlagConfiguration
metadata:
  name: my-flags
spec:
  featureFlagSpec: |
    {
      "flags": {
        "new-ui-enabled": {
          "state": "ENABLED",
          "variants": {
            "on": true,
            "off": false
          },
          "defaultVariant": "off"
        },
        "checkout-flow": {
          "state": "ENABLED",
          "variants": {
            "v1": "classic",
            "v2": "express"
          },
          "defaultVariant": "v1",
          "targeting": {
            "if": [
              {"in": ["beta-user", {"var": "userGroup"}]},
              "v2", "v1"
            ]
          }
        }
      }
    }
